            .collection("pinned_conversations")
            .document(conversationId)
        if (pinned) {
            docRef.set(
                mapOf(
                    "conversationId" to conversationId,
                    "pinnedAt" to FieldValue.serverTimestamp()
                )
            ).await()
        } else {
            docRef.delete().await()
        }
    }

