    /**
     * 设置会话对某个用户的屏蔽状态
     */
    suspend fun setConversationParticipantBlocked(conversationId: String, participantId: String, blocked: Boolean): Result<Unit> = runCatching {
        val field = "blockedParticipants.$participantId"
        val docRef = conversationsCollection.document(conversationId)
        if (blocked) {
            docRef.update(field, true).await()
        } else {
            docRef.update(field, FieldValue.delete()).await()
        }
    }

    /**
     * 检查用户是否被屏蔽
     */
    suspend fun isConversationParticipantBlocked(conversationId: String, participantId: String): Result<Boolean> = runCatching {
        val snapshot = conversationsCollection
            .document(conversationId)
            .get()
            .await()
        val blockedMap = snapshot.get("blockedParticipants") as? Map<*, *> ?: emptyMap<String, Boolean>()
        blockedMap[participantId] == true
    }

    // ==================== 会话相关 Conversation Operations ====================

    /**
     * 创建或获取私聊会话
     *
     * 优化逻辑：
     * 1. 从 currentUserId 的 contacts 中查找是否已有与 otherUserId 的会话
     * 2. 如果找到，返回该会话
     * 3. 如果没有，创建新会话并同时在 currentUserId 的 contacts 中添加联系人信息
     */
    suspend fun createOrGetPrivateConversation(currentUserId: String, otherUserId: String): Result<Conversation> = runCatching {
        Log.d(TAG, "createOrGetPrivateConversation: currentUser=$currentUserId, otherUser=$otherUserId")

        // 1. 从当前用户的 contacts 中查找是否已有与 otherUserId 的联系人
        val contactDoc = usersCollection
            .document(currentUserId)
            .collection("contacts")
            .document(otherUserId)
            .get()
            .await()

        val existingContact = contactDoc.toObject(Contact::class.java)

        // 2. 如果联系人存在且有 conversationId，获取该会话
        if (existingContact != null && existingContact.conversationId.isNotEmpty()) {
            Log.d(TAG, "Found existing conversation: ${existingContact.conversationId}")
            val conversation = getConversation(existingContact.conversationId).getOrNull()
            if (conversation != null) {
                return@runCatching conversation
            }
            Log.w(TAG, "Conversation ${existingContact.conversationId} not found in Firestore, creating new one")
        }

        // 3. 如果没有找到会话，创建新会话
        Log.d(TAG, "Creating new conversation")
        val otherUser = getUser(otherUserId).getOrNull()
        val conversationId = conversationsCollection.document().id

        val conversation = Conversation(
            id = conversationId,
            type = ConversationType.PRIVATE,
            name = otherUser?.username ?: "",
            avatarUrl = otherUser?.avatarUrl ?: "",
            participants = listOf(currentUserId, otherUserId),
            createdBy = currentUserId,
            unreadCounts = mapOf(currentUserId to 0, otherUserId to 0)
        )

        // 保存会话到 Firestore
        conversationsCollection.document(conversationId).set(conversation.toMap()).await()
        Log.d(TAG, "Conversation created: $conversationId")

        // 4. 在两个用户的 contacts 中都添加联系人信息（双向关系）
        val currentTime = System.currentTimeMillis()

        // 获取两个用户的详细信息
        val currentUser = getUser(currentUserId).getOrNull()

        // 为 currentUserId 添加 otherUserId 作为联系人
        val contactForCurrentUser = Contact(
            userId = currentUserId,
            contactId = otherUserId,
            contactName = otherUser?.username ?: "",
            contactAvatarUrl = otherUser?.avatarUrl ?: "",
            type = "PRIVATE",
            conversationId = conversationId,
            isBlocked = false,
            addedAt = currentTime
        )
        addContact(contactForCurrentUser).getOrThrow()
        Log.d(TAG, "Contact added for currentUser: $currentUserId -> $otherUserId")

        // 为 otherUserId 添加 currentUserId 作为联系人
        val contactForOtherUser = Contact(
            userId = otherUserId,
            contactId = currentUserId,
            contactName = currentUser?.username ?: "",
            contactAvatarUrl = currentUser?.avatarUrl ?: "",
            type = "PRIVATE",
            conversationId = conversationId,
            isBlocked = false,
            addedAt = currentTime
        )
        addContact(contactForOtherUser).getOrThrow()
        Log.d(TAG, "Contact added for otherUser: $otherUserId -> $currentUserId")

        conversation
    }

    /**
     * 创建群聊会话
     */
    suspend fun createGroupConversation(
        name: String,
        avatarUrl: String,
        participants: List<String>,
        createdBy: String
    ): Result<Conversation> = runCatching {
        val conversationId = conversationsCollection.document().id
        val conversation = Conversation(
            id = conversationId,
            type = ConversationType.GROUP,
            name = name,
            avatarUrl = avatarUrl,
            participants = participants,
            createdBy = createdBy,
            unreadCounts = participants.associateWith { 0 }
        )
        conversationsCollection.document(conversationId).set(conversation.toMap()).await()
        conversation
    }

    /**
     * 获取用户的会话列表（包括个人会话和群组会话）
     * 通过用户的联系人列表获取 conversationId，而不是查询所有会话
     *
     * 支持：
     * - 个人联系人会话（type = "PRIVATE"）
     * - 群组会话（type = "GROUP"）
     */
    suspend fun getUserConversations(userId: String): Result<List<Conversation>> = runCatching {
        // 1. 获取用户的所有联系人（包括个人和群组）
        val contacts = getContacts(userId).getOrNull() ?: emptyList()

        // 2. 过滤出已确认的联系人
        // 只保留：isNew = false && isPending = false 的联系人和群组
        val confirmedContacts = contacts.filter { contact ->
            // 群组直接显示
            if (contact.type == "GROUP") {
                true
            } else {
                // 个人联系人：必须是已确认的好友（isNew = false && isPending = false）
                // isNew = false, isPending = true: 已发送请求，等待对方接受 → 不显示
                // isNew = true, isPending = false: 收到请求，等待我接受 → 不显示
                // isNew = false, isPending = false: 已确认的好友 → 显示
                !contact.isNew && !contact.isPending
            }
        }

        Log.d(TAG, "getUserConversations: Total contacts: ${contacts.size}, Confirmed: ${confirmedContacts.size}, Pending: ${contacts.size - confirmedContacts.size}")

        // 3. 提取所有 conversationId（过滤掉空的）
        // 无论是个人联系人还是群组，都有 conversationId 字段
        val conversationIds = confirmedContacts.mapNotNull { it.conversationId.takeIf { id -> id.isNotEmpty() } }

        Log.d(TAG, "getUserConversations: Found ${conversationIds.size} conversation IDs from confirmed contacts (including groups)")

        // 4. 如果没有会话，直接返回空列表
        if (conversationIds.isEmpty()) {
            return@runCatching emptyList()
        }

        // 5. 批量获取会话信息
        // Firebase 的 whereIn 限制为 10 个元素，需要分批查询
        val conversations = mutableListOf<Conversation>()
        conversationIds.chunked(10).forEach { chunk ->
            val snapshot = conversationsCollection
                .whereIn("__name__", chunk) // 使用文档 ID 查询
                .whereEqualTo("isActive", true)
                .get()
                .await()

            snapshot.documents.mapNotNullTo(conversations) { doc ->
                doc.toObject(Conversation::class.java)?.copy(id = doc.id)
            }
        }

        Log.d(TAG, "getUserConversations: Retrieved ${conversations.size} conversations from Firestore")

        // 6. 按最后消息时间排序
        conversations.sortedByDescending { it.lastMessageTime }
    }

    /**
     * 监听用户的会话列表（包括个人会话和群组会话）
     * 通过用户的联系人列表获取 conversationId，而不是查询所有会话
     *
     * 支持：
     * - 个人联系人会话（type = "PRIVATE"）
     * - 群组会话（type = "GROUP"）
     *
     * 注意：此方法会先监听联系人列表变化，然后监听对应的会话
     */
    fun observeUserConversations(userId: String): Flow<List<Conversation>> = callbackFlow {
        // 监听用户的联系人列表（包括个人联系人和群组）
        val contactsListener = usersCollection
            .document(userId)
            .collection("contacts")
            .whereEqualTo("isBlocked", false)
            .addSnapshotListener { contactsSnapshot, contactsError ->
                if (contactsError != null) {
                    Log.e(TAG, "Error observing contacts", contactsError)
                    close(contactsError)
                    return@addSnapshotListener
                }

                val contacts = contactsSnapshot?.toObjects(Contact::class.java) ?: emptyList()

                // 过滤出已确认的联系人
                // 只保留：isNew = false && isPending = false 的联系人和群组
                val confirmedContacts = contacts.filter { contact ->
                    // 群组直接显示
                    if (contact.type == "GROUP") {
                        true
                    } else {
                        // 个人联系人：必须是已确认的好友（isNew = false && isPending = false）
                        !contact.isNew && !contact.isPending
                    }
                }

                Log.d(TAG, "observeUserConversations: Total contacts: ${contacts.size}, Confirmed: ${confirmedContacts.size}, Pending: ${contacts.size - confirmedContacts.size}")

                // 提取所有 conversationId（无论是个人还是群组）
                val conversationIds = confirmedContacts.mapNotNull {
                    it.conversationId.takeIf { id -> id.isNotEmpty() }
                }

                Log.d(TAG, "observeUserConversations: Found ${conversationIds.size} conversation IDs from confirmed contacts (including groups)")
                Log.d(TAG, "observeUserConversations: Contacts breakdown - ${confirmedContacts.count { it.type == "GROUP" }} groups, ${confirmedContacts.count { it.type == "PRIVATE" }} private")

                if (conversationIds.isEmpty()) {
                    trySend(emptyList())
                    return@addSnapshotListener
                }

                // 监听这些会话的变化
                // 由于 Firebase 不支持直接监听多个文档 ID，我们需要分批监听或使用组合查询
                // 这里使用一个简单的方法：查询所有匹配的会话
                conversationsCollection
                    .whereEqualTo("isActive", true)
                    .addSnapshotListener { conversationsSnapshot, conversationsError ->
                        if (conversationsError != null) {
                            Log.e(TAG, "Error observing conversations", conversationsError)
                            close(conversationsError)
                            return@addSnapshotListener
                        }

                        // 过滤出属于用户的会话（包括个人和群组）
                        val allConversations = conversationsSnapshot?.documents?.mapNotNull { doc ->
                            if (conversationIds.contains(doc.id)) {
                                doc.toObject(Conversation::class.java)?.copy(id = doc.id)
                            } else null
                        } ?: emptyList()

                        Log.d(TAG, "observeUserConversations: Received ${allConversations.size} conversations from Firestore")
                        Log.d(TAG, "observeUserConversations: Breakdown - ${allConversations.count { it.type == ConversationType.GROUP }} groups, ${allConversations.count { it.type == ConversationType.PRIVATE }} private")

                        // 在客户端按时间排序
                        val sortedConversations = allConversations.sortedByDescending { it.lastMessageTime }
                        trySend(sortedConversations)
                    }
            }

        awaitClose {
            // 注意：这里只移除最外层的监听器
            // 内层监听器会在外层监听器触发时自动更新
            contactsListener.remove()
        }
    }

    /**
     * 获取单个会话信息
     */
    suspend fun getConversation(conversationId: String): Result<Conversation?> = runCatching {
        val doc = conversationsCollection
            .document(conversationId)
            .get()
            .await()

        // 手动映射并设置 id
        doc.toObject(Conversation::class.java)?.copy(id = doc.id)
    }

    /**
     * 生成新的会话 ID
     */
    fun generateConversationId(): String {
        return conversationsCollection.document().id
    }

    /**
     * 创建会话（不自动创建 contacts）
     */
    suspend fun createConversation(conversation: Conversation): Result<Unit> = runCatching {
        conversationsCollection
            .document(conversation.id)
            .set(conversation.toMap())
            .await()
    }

    /**
     * 更新会话信息
     */
    suspend fun updateConversation(conversation: Conversation): Result<Unit> = runCatching {
        conversationsCollection
            .document(conversation.id)
            .set(conversation.toMap())
            .await()
    }

    /**
     * 删除会话（标记为不活跃）
     */
    suspend fun deleteConversation(conversationId: String): Result<Unit> = runCatching {
        conversationsCollection
            .document(conversationId)
            .update("isActive", false)
            .await()
    }

    // ==================== 消息相关 Message Operations ====================

    /**
     * 发送消息
     */
    suspend fun sendMessage(message: Message): Result<Message> = runCatching {
        val messageId = conversationsCollection
            .document(message.conversationId)
            .collection("messages")
            .document().id

        val messageWithId = message.copy(id = messageId)

        // 保存消息
        conversationsCollection
            .document(message.conversationId)
            .collection("messages")
            .document(messageId)
            .set(messageWithId.toMap())
            .await()

        // 更新会话的最后消息信息
        val conversation = getConversation(message.conversationId).getOrNull()
        conversation?.let {
            val updatedUnreadCounts = it.unreadCounts.toMutableMap()
            it.participants.forEach { participantId ->
                if (participantId != message.senderId) {
                    updatedUnreadCounts[participantId] = (updatedUnreadCounts[participantId] ?: 0) + 1
                }
            }

            conversationsCollection
                .document(message.conversationId)
                .update(
                    mapOf(
                        "lastMessage" to message.content,
                        "lastMessageTime" to message.timestamp,
                        "unreadCounts" to updatedUnreadCounts
                    )
                )
                .await()
        }

        messageWithId
    }

    /**
     * 获取会话的消息列表
     */
    suspend fun getMessages(conversationId: String, limit: Int = 50): Result<List<Message>> = runCatching {
        val snapshot = conversationsCollection
            .document(conversationId)
            .collection("messages")
            .orderBy("timestamp", Query.Direction.DESCENDING)
            .limit(limit.toLong())
            .get()
            .await()

        // 手动映射，确保 id 字段被正确设置为文档 ID
        snapshot.documents.mapNotNull { doc ->
            doc.toObject(Message::class.java)?.copy(id = doc.id)
        }.reversed()
    }

    /**
     * 监听会话的新消息
     */
    fun observeMessages(conversationId: String): Flow<List<Message>> = callbackFlow {
        val listener = conversationsCollection
            .document(conversationId)
            .collection("messages")
            .orderBy("timestamp", Query.Direction.ASCENDING)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    close(error)
                    return@addSnapshotListener
                }
                // 手动映射，确保 id 字段被正确设置为文档 ID
                val messages = snapshot?.documents?.mapNotNull { doc ->
                    doc.toObject(Message::class.java)?.copy(id = doc.id)
                } ?: emptyList()
                trySend(messages)
            }
        awaitClose { listener.remove() }
    }

    /**
     * 标记消息为已读
     */
    suspend fun markMessageAsRead(conversationId: String, messageId: String, userId: String): Result<Unit> = runCatching {
        val messageRef = conversationsCollection
            .document(conversationId)
            .collection("messages")
            .document(messageId)

        val message = messageRef.get().await().toObject(Message::class.java)
        message?.let {
            if (!it.readBy.contains(userId)) {
                val updatedReadBy = it.readBy + userId
                messageRef.update("readBy", updatedReadBy).await()
            }
        }
    }

    /**
     * 清空会话未读数
     */
    suspend fun clearUnreadCount(conversationId: String, userId: String): Result<Unit> = runCatching {
        val conversation = getConversation(conversationId).getOrNull()
        conversation?.let {
            val updatedUnreadCounts = it.unreadCounts.toMutableMap()
            updatedUnreadCounts[userId] = 0

            conversationsCollection
                .document(conversationId)
                .update("unreadCounts", updatedUnreadCounts)
                .await()
        }
    }

    /**
     * 删除消息
     */
    suspend fun deleteMessage(conversationId: String, messageId: String): Result<Unit> = runCatching {
        conversationsCollection
            .document(conversationId)
            .collection("messages")
            .document(messageId)
            .update("isDeleted", true)
            .await()
    }

    // ==================== 群组相关 Group Operations ====================

    /**
     * 创建群组
     */
    suspend fun createGroup(group: Group): Result<Group> = runCatching {
        val groupId = groupsCollection.document().id
        val groupWithId = group.copy(id = groupId)
        groupsCollection.document(groupId).set(groupWithId.toMap()).await()

        // 同时创建对应的群聊会话
        createGroupConversation(
            name = group.name,
            avatarUrl = group.avatarUrl,
            participants = group.memberIds,
            createdBy = group.ownerId
        )

        groupWithId
    }

    /**
     * 获取群组信息
     */
    suspend fun getGroup(groupId: String): Result<Group?> = runCatching {
        groupsCollection
            .document(groupId)
            .get()
            .await()
            .toObject(Group::class.java)
    }

    /**
     * 更新群组信息
     */
    suspend fun updateGroup(group: Group): Result<Unit> = runCatching {
        groupsCollection
            .document(group.id)
            .set(group.toMap())
            .await()
    }

    /**
     * 添加群成员
     */
    suspend fun addGroupMembers(groupId: String, memberIds: List<String>): Result<Unit> = runCatching {
        val group = getGroup(groupId).getOrNull() ?: throw Exception("Group not found")
        val updatedMembers = (group.memberIds + memberIds).distinct()

        groupsCollection
            .document(groupId)
            .update("memberIds", updatedMembers)
            .await()

        // 更新对应会话的参与者列表
        conversationsCollection
            .document(groupId)
            .update("participants", updatedMembers)
            .await()
    }

    /**
     * 移除群成员
     */
    suspend fun removeGroupMember(groupId: String, memberId: String): Result<Unit> = runCatching {
        val group = getGroup(groupId).getOrNull() ?: throw Exception("Group not found")
        val updatedMembers = group.memberIds.filter { it != memberId }

        groupsCollection
            .document(groupId)
            .update("memberIds", updatedMembers)
            .await()

        // 更新对应会话的参与者列表
        conversationsCollection
            .document(groupId)
            .update("participants", updatedMembers)
            .await()
    }

    /**
     * 转让群主
     */
    suspend fun transferGroupOwnership(groupId: String, newOwnerId: String): Result<Unit> = runCatching {
        val group = getGroup(groupId).getOrNull() ?: throw Exception("Group not found")

        groupsCollection
            .document(groupId)
            .update(
                mapOf(
                    "ownerId" to newOwnerId,
                    "adminIds" to (group.adminIds + group.ownerId).distinct()
                )
            )
            .await()
    }

    /**
     * 解散群组
     */
    suspend fun dismissGroup(groupId: String): Result<Unit> = runCatching {
        // 删除群组信息
        groupsCollection.document(groupId).delete().await()

        // 标记会话为不活跃
        deleteConversation(groupId)
    }
}

/**
 * ChatRepository.kt
 *
 * 聊天数据仓库 - 处理聊天相关的业务逻辑
 * Chat Repository - Handles chat-related business logic
 *
 * 职责：
 * - 会话管理（创建、获取、更新、删除）
 * - 消息管理（发送、接收、标记已读）
 * - 群组管理（创建、更新、成员管理）
 * - 联系人管理
 *
 * @author CS501 Team
 */
package com.example.cs501_micro_chat.data.repository

import com.example.cs501_micro_chat.data.model.*
import com.example.cs501_micro_chat.data.remote.FirebaseDataSource
import com.google.firebase.auth.FirebaseAuth
import kotlinx.coroutines.flow.Flow
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class ChatRepository @Inject constructor(
    private val firebaseDataSource: FirebaseDataSource,
    private val auth: FirebaseAuth
) {

    private val currentUserId: String?
        get() = auth.currentUser?.uid

    // ==================== 会话相关 Conversation Operations ====================

    /**
     * 获取用户的所有会话
     */
    suspend fun getUserConversations(): Result<List<Conversation>> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.getUserConversations(userId)
    }

    /**
     * 监听用户的会话列表
     */
    fun observeUserConversations(): Flow<List<Conversation>>? {
        val userId = currentUserId ?: return null
        return firebaseDataSource.observeUserConversations(userId)
    }

    /**
     * 创建或获取与某用户的私聊会话
     */
    suspend fun createOrGetPrivateConversation(otherUserId: String): Result<Conversation> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.createOrGetPrivateConversation(userId, otherUserId)
    }

    /**
     * 获取会话信息
     */
    suspend fun getConversation(conversationId: String): Result<Conversation?> {
        return firebaseDataSource.getConversation(conversationId)
    }

    /**
     * 更新会话信息
     */
    suspend fun updateConversation(conversation: Conversation): Result<Unit> {
        return firebaseDataSource.updateConversation(conversation)
    }

    /**
     * 删除会话
     */
    suspend fun deleteConversation(conversationId: String): Result<Unit> {
        return firebaseDataSource.deleteConversation(conversationId)
    }

    // ==================== 消息相关 Message Operations ====================

    /**
     * 发送消息
     */
    suspend fun sendMessage(
        conversationId: String,
        content: String,
        type: MessageType = MessageType.TEXT,
        mediaUrl: String = ""
    ): Result<Message> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))

        val isBlocked = firebaseDataSource.isConversationParticipantBlocked(conversationId, userId).getOrElse { false }

        // 获取当前用户信息
        val userResult = firebaseDataSource.getUser(userId)
        val user = userResult.getOrNull() ?: return Result.failure(Exception("Failed to get user info"))

        val message = Message(
            conversationId = conversationId,
            senderId = userId,
            senderName = user.username,
            senderAvatarUrl = user.avatarUrl,
            content = content,
            type = type,
            mediaUrl = mediaUrl,
            timestamp = System.currentTimeMillis(),
            readBy = listOf(userId),
            status = if (isBlocked) MessageStatus.FAILED else MessageStatus.SENT
        )

        return firebaseDataSource.sendMessage(message)
    }

    /**
     * 获取会话的消息列表
     */
    suspend fun getMessages(conversationId: String, limit: Int = 50): Result<List<Message>> {
        return firebaseDataSource.getMessages(conversationId, limit)
    }

    /**
     * 监听会话的新消息
     */
    fun observeMessages(conversationId: String): Flow<List<Message>> {
        return firebaseDataSource.observeMessages(conversationId)
    }

    /**
     * 标记消息为已读
     */
    suspend fun markMessageAsRead(conversationId: String, messageId: String): Result<Unit> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.markMessageAsRead(conversationId, messageId, userId)
    }

    /**
     * 清空会话未读数
     */
    suspend fun clearUnreadCount(conversationId: String): Result<Unit> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.clearUnreadCount(conversationId, userId)
    }

    /**
     * 删除消息
     */
    suspend fun deleteMessage(conversationId: String, messageId: String): Result<Unit> {
        return firebaseDataSource.deleteMessage(conversationId, messageId)
    }

    // ==================== 群组相关 Group Operations ====================

    /**
     * 创建群组
     */
    suspend fun createGroup(
        name: String,
        description: String,
        avatarUrl: String,
        memberIds: List<String>
    ): Result<Group> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))

        val group = Group(
            name = name,
            description = description,
            avatarUrl = avatarUrl,
            ownerId = userId,
            adminIds = listOf(userId),
            memberIds = memberIds + userId // 确保创建者也在成员列表中
        )

        return firebaseDataSource.createGroup(group)
    }

    /**
     * 获取群组信息
     */
    suspend fun getGroup(groupId: String): Result<Group?> {
        return firebaseDataSource.getGroup(groupId)
    }

    /**
     * 更新群组信息
     */
    suspend fun updateGroup(group: Group): Result<Unit> {
        return firebaseDataSource.updateGroup(group)
    }

    /**
     * 添加群成员
     */
    suspend fun addGroupMembers(groupId: String, memberIds: List<String>): Result<Unit> {
        return firebaseDataSource.addGroupMembers(groupId, memberIds)
    }

    /**
     * 移除群成员
     */
    suspend fun removeGroupMember(groupId: String, memberId: String): Result<Unit> {
        return firebaseDataSource.removeGroupMember(groupId, memberId)
    }

    /**
     * 退出群组
     */
    suspend fun leaveGroup(groupId: String): Result<Unit> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.removeGroupMember(groupId, userId).onSuccess {
            firebaseDataSource.setPinnedConversation(userId, groupId, false)
            firebaseDataSource.setConversationParticipantBlocked(groupId, userId, true)
        }
    }

    /**
     * 转让群主
     */
    suspend fun transferGroupOwnership(groupId: String, newOwnerId: String): Result<Unit> {
        return firebaseDataSource.transferGroupOwnership(groupId, newOwnerId)
    }

    /**
     * 解散群组
     */
    suspend fun dismissGroup(groupId: String): Result<Unit> {
        return firebaseDataSource.dismissGroup(groupId)
    }

    // ==================== 联系人相关 Contact Operations ====================

    /**
     * 发送好友请求
     * 1. 在目标用户的 contacts 中添加当前用户，设置 isNew = true（待确认）
     * 2. 在当前用户的 contacts 中添加目标用户，设置 isPending = true（已发送，等待接受）
     */
    suspend fun sendFriendRequest(targetUserId: String, alias: String = ""): Result<Unit> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))

        try {
            // 获取当前用户信息
            val currentUserResult = firebaseDataSource.getUser(userId)
            val currentUser = currentUserResult.getOrNull()
                ?: return Result.failure(Exception("Current user not found"))

            // 获取目标用户信息
            val targetUserResult = firebaseDataSource.getUser(targetUserId)
            val targetUser = targetUserResult.getOrNull()
                ?: return Result.failure(Exception("Target user not found"))

            // 在目标用户的 contacts 中创建一个待确认的联系人（当前用户）
            val receiverContact = Contact(
                userId = targetUserId, // 目标用户的ID
                contactId = userId, // 当前用户的ID
                contactName = currentUser.username,
                contactAvatarUrl = currentUser.avatarUrl,
                alias = "",
                type = "PRIVATE",
                isNew = true, // 标记为待确认（接收者看到的）
                isPending = false,
                conversationId = "" // 暂时不设置 conversationId
            )
            firebaseDataSource.addContact(receiverContact).getOrThrow()

            // 在当前用户的 contacts 中创建一个已发送的联系人（目标用户）
            val senderContact = Contact(
                userId = userId, // 当前用户的ID
                contactId = targetUserId, // 目标用户的ID
                contactName = targetUser.username,
                contactAvatarUrl = targetUser.avatarUrl,
                alias = alias,
                type = "PRIVATE",
                isNew = false,
                isPending = true, // 标记为已发送等待接受（发送者看到的）
                conversationId = "" // 暂时不设置 conversationId
            )
            firebaseDataSource.addContact(senderContact).getOrThrow()

            return Result.success(Unit)
        } catch (e: Exception) {
            return Result.failure(e)
        }
    }

    /**
     * 接受好友请求
     * 1. 创建私聊会话
     * 2. 将当前用户 contacts 中的 isNew 设置为 false，添加 conversationId
     * 3. 将请求者 contacts 中的 isPending 设置为 false，添加 conversationId
     */
    suspend fun acceptFriendRequest(requesterId: String): Result<Unit> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))

        try {
            // 获取请求者信息
            val requesterResult = firebaseDataSource.getUser(requesterId)
            val requester = requesterResult.getOrNull()
                ?: return Result.failure(Exception("Requester not found"))

            // 获取当前用户信息
            val currentUserResult = firebaseDataSource.getUser(userId)
            val currentUser = currentUserResult.getOrNull()
                ?: return Result.failure(Exception("Current user not found"))

            // 直接创建新的私聊会话，不使用 createOrGetPrivateConversation
            // 因为后者会自动创建 contacts 并覆盖我们的状态
            val conversationId = firebaseDataSource.generateConversationId()
            val conversation = Conversation(
                id = conversationId,
                type = ConversationType.PRIVATE,
                name = requester.username,
                avatarUrl = requester.avatarUrl,
                participants = listOf(userId, requesterId),
                createdBy = userId,
                unreadCounts = mapOf(userId to 0, requesterId to 0)
            )

            // 保存会话到 Firebase
            firebaseDataSource.createConversation(conversation).getOrThrow()

            // 更新当前用户的 contact（将 isNew 设置为 false，添加 conversationId）
            val myContact = Contact(
                userId = userId,
                contactId = requesterId,
                contactName = requester.username,
                contactAvatarUrl = requester.avatarUrl,
                type = "PRIVATE",
                isNew = false, // 从 true 变为 false
                isPending = false,
                conversationId = conversationId
            )
            firebaseDataSource.addContact(myContact).getOrThrow()

            // 更新请求者的 contact（将 isPending 设置为 false，添加 conversationId）
            val theirContact = Contact(
                userId = requesterId,
                contactId = userId,
                contactName = currentUser.username,
                contactAvatarUrl = currentUser.avatarUrl,
                type = "PRIVATE",
                isNew = false,
                isPending = false, // 从 true 变为 false
                conversationId = conversationId
            )
            firebaseDataSource.addContact(theirContact).getOrThrow()

            return Result.success(Unit)
        } catch (e: Exception) {
            return Result.failure(e)
        }
    }

    /**
     * 拒绝好友请求
     * 删除当前用户 contacts 中的该联系人
     */
    suspend fun rejectFriendRequest(requesterId: String): Result<Unit> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.removeContact(userId, requesterId)
    }

    /**
     * 添加联系人（旧版本，保留兼容性）
     */
    suspend fun addContact(contactId: String, alias: String = ""): Result<Unit> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))

        // 获取联系人信息
        val contactUserResult = firebaseDataSource.getUser(contactId)
        val contactUser = contactUserResult.getOrNull()
            ?: return Result.failure(Exception("Contact user not found"))

        // 创建或获取私聊会话
        val conversationResult = createOrGetPrivateConversation(contactId)
        val conversation = conversationResult.getOrNull()
            ?: return Result.failure(Exception("Failed to create conversation"))

        val contact = Contact(
            userId = userId,
            contactId = contactId,
            contactName = contactUser.username,
            contactAvatarUrl = contactUser.avatarUrl,
            alias = alias,
            conversationId = conversation.id
        )

        return firebaseDataSource.addContact(contact)
    }

    /**
     * 获取联系人列表
     */
    suspend fun getContacts(): Result<List<Contact>> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.getContacts(userId)
    }

    /**
     * 获取单个联系人
     */
    suspend fun getContact(contactId: String): Result<Contact?> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.getContact(userId, contactId)
    }

    /**
     * 监听联系人列表
     */
    fun observeContacts(): Flow<List<Contact>>? {
        val userId = currentUserId ?: return null
        return firebaseDataSource.observeContacts(userId)
    }

    /**
     * 删除联系人
     */
    suspend fun deleteContact(contactId: String): Result<Unit> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        val contact = firebaseDataSource.getContact(userId, contactId).getOrNull()
        val conversationId = contact?.conversationId
        val deleteResult = firebaseDataSource.deleteContact(userId, contactId)
        deleteResult.onSuccess {
            if (!conversationId.isNullOrBlank()) {
                firebaseDataSource.setPinnedConversation(userId, conversationId, false)
                firebaseDataSource.setConversationParticipantBlocked(conversationId, contactId, true)
                firebaseDataSource.setConversationParticipantBlocked(conversationId, userId, true)
            }
        }
        return deleteResult
    }

    /**
     * 更新联系人备注
     */
    suspend fun updateContactAlias(contactId: String, alias: String): Result<Unit> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.updateContactAlias(userId, contactId, alias)
    }

    /**
     * 监听置顶会话
     */
    fun observePinnedConversations(): Flow<Set<String>>? {
        val userId = currentUserId ?: return null
        return firebaseDataSource.observePinnedConversations(userId)
    }

    /**
     * 设置置顶状态
     */
    suspend fun setPinnedConversation(conversationId: String, pinned: Boolean): Result<Unit> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.setPinnedConversation(userId, conversationId, pinned)
    }

    /**
     * 检查会话是否置顶
     */
    suspend fun isConversationPinned(conversationId: String): Result<Boolean> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.isConversationPinned(userId, conversationId)
    }

    /**
     * 更新联系人置顶状态（用于同步联系人列表中的星标）
     */
    suspend fun updateContactFavorite(contactId: String, isFavorite: Boolean): Result<Unit> {
        val userId = currentUserId ?: return Result.failure(Exception("User not logged in"))
        return firebaseDataSource.updateContactFavorite(userId, contactId, isFavorite)
    }

    /**
     * 搜索用户
     */
    suspend fun searchUsers(query: String): Result<List<User>> {
        return firebaseDataSource.searchUsers(query)
    }

    // ==================== 用户相关 User Operations ====================

    /**
     * 获取用户信息
     */
    suspend fun getUser(userId: String): Result<User?> {
        return firebaseDataSource.getUser(userId)
    }

    /**
     * 批量获取用户信息
     */
    suspend fun getUsers(userIds: List<String>): Result<Map<String, User>> {
        return firebaseDataSource.getUsers(userIds)
    }

}

